from __future__ import annotations
import contextlib, io, itertools, logging, warnings
import numpy as np
import pandas as pd
import pypsa
logging.getLogger('pypsa').setLevel(logging.CRITICAL); logging.getLogger('linopy').setLevel(logging.CRITICAL)
snapshots = pd.MultiIndex.from_product([[2020, 2030], ['first', 'second']], names=['period', 'step'])
expected = {(False, False): [6,5,4,3], (False,True): [6,5,6,5], (True,False): [6,5,4,3], (True,True): [6,5,6,5]}
for component in ['Store','StorageUnit']:
  for pp, initpp in itertools.product([False,True], repeat=2):
    n=pypsa.Network(); n.set_snapshots(snapshots); n.investment_periods=[2020,2030]; n.add('Bus','bus'); n.add('Load','load',bus='bus',p_set=1)
    if component=='Store': n.add(component,'storage',bus='bus',e_nom=20,e_initial=7,marginal_cost=1,e_cyclic=False,e_cyclic_per_period=pp,e_initial_per_period=initpp)
    else: n.add(component,'storage',bus='bus',p_nom=20,max_hours=1,state_of_charge_initial=7,marginal_cost=1,cyclic_state_of_charge=False,cyclic_state_of_charge_per_period=pp,state_of_charge_initial_per_period=initpp)
    with warnings.catch_warnings(),contextlib.redirect_stdout(io.StringIO()),contextlib.redirect_stderr(io.StringIO()): warnings.simplefilter('ignore'); status,condition=n.optimize(solver_options={'output_flag':False})
    assert (status,condition)==('ok','optimal'); values=n.stores_t.e.storage if component=='Store' else n.storage_units_t.state_of_charge.storage; np.testing.assert_allclose(values,expected[(pp,initpp)])
  for initpp in [False,True]:
    n=pypsa.Network(); n.set_snapshots(snapshots); n.investment_periods=[2020,2030]; n.add('Bus','bus')
    if component=='Store': n.add(component,'storage',bus='bus',e_nom=20,e_initial=7,e_cyclic=True,e_cyclic_per_period=True,e_initial_per_period=initpp,standing_loss=.1,e_set=[4,np.nan,4,np.nan],marginal_cost_storage=.01)
    else: n.add(component,'storage',bus='bus',p_nom=20,max_hours=1,state_of_charge_initial=7,cyclic_state_of_charge=True,cyclic_state_of_charge_per_period=True,state_of_charge_initial_per_period=initpp,standing_loss=.1,state_of_charge_set=[4,np.nan,4,np.nan],marginal_cost_storage=.01)
    with warnings.catch_warnings(),contextlib.redirect_stdout(io.StringIO()),contextlib.redirect_stderr(io.StringIO()): warnings.simplefilter('ignore'); status,condition=n.optimize(solver_options={'output_flag':False})
    assert (status,condition)==('ok','optimal'); values=n.stores_t.e.storage if component=='Store' else n.storage_units_t.state_of_charge.storage; np.testing.assert_allclose(values.iloc[[0,2]],[4,4]); assert not np.isclose(values.iloc[1]*.9,7); assert not np.isclose(values.iloc[3]*.9,7)
print('boundary policy matrix passed for Store and StorageUnit')
